INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62658423', 62658423, 'analyze_legacy', 'Kota Dumai', 'kabkota', 'DINAS KOMUNIKASI, INFORMATIKA, STATISTIK DAN PERSANDIAN', 'Belanja Kawat/Faksimili/Internet/TV Berlangganan', 'Jasa Lainnya', 'E-Purchasing', 'Riau, Dumai (Kota)', 960000000, 'January 2026', 'APBD', 1, 1, '12 Bulan', 'Belanja Bandwith Jaringan Internet Internasional Dedicated', 'Target / sasaran yang ingin dicapai dalam kegiatan ini adalah Penyediaan akses Internet Internasional (IX) dengan Kapasitas 500 Mbps dengan jaminan Bandwidth Dedicated 1:1 via Fiber Optik dengan Sasaran : 1. Menyediakan Link Metro antara NOC, Kantor BPKAD dan MPP. 2. Menyediakan Link Metro pada satuan perangkat kerja yang ada di Pemerintah Kota Dumai sebanyak 40 OPD, 10 Puskesmas, 36 Kantor Kelurahan, UPT, LPMK dan beberapa tempat layanan publik; 3. Menyediakan Perangkat Routing BGP di Pusat Komputasi Diskominfotiksan Kota Dumai; 4. Manajemen Bandwitdh terpusat di Dinas Komunikasi, Informatika, Statistik dan Persandian Kota Dumai; 5. Bandwitdh ratio CIR (Committed Information Rate) 1:1 upstream dan downstream dengan sifat koneksi dedicated (non share/koneksi clear channel); 6. Media Akses menggunakan FO (Fiber Optic)/Jaringan Wireless; 7. Koneksi akhir menggunakan Optical Network Transmition (ONT) dan Ethernet (RJ45); 8. Minimum ketersediaan Service layer Availability (SLA) minimal 99,2% (714 Jam 15 Menit) dalam sebulan (720 Jam ) dengan masa kewajaran apabila internet down/mati sebesar 0,08%/ 5 jam 45 menit (pembulatan 6 jam/bulan) setiap bulanya dan mendapatkan laporan performance dan penggunaan (MRTG) jika SLA berkurang dari nilai tersebut dapat digunakan sebagai pengurang pembayaran pekerjaan kepada penyedia jasa layanan internet; 9. Fasilitas Layanan tenaga ahli atau engineer professional yang siap melayani dan memantau selama 24 jam x 7 hari dalam seminggu; 10. Batas Maksimal apabila terjadi down time pada layanan internet maksimal 3% dalam waktu setahun (akumulasi dalam waktu setahun); 11. Penyedia harus memiliki POP (Point of Presense) atau yang terdekat dengan Pemerintah Kota Dumai; 12. Penyedia harus memiliki kantor yang berdomisili di Kota Dumai; 13. Media koneksi/Backbone koneksi jaringan Bandwitdh menggunakan Fiber Optik; 14. Menyediakan Starlink di kelurahan Marginal; 15. Menyediakan jalur cadangan untuk koneksi ke NOC Dinas Komunikasi, Informatika, Statistik dan Persandian Kota Dumai apabila terjadi loss koneksi; 16. Mengikutsertakan pelatihan Teknis pengelolaan Network Management System bagi ASN/Tim Teknis Dinas Komunikasi, Informatika, Statistik dan Persandian Kota Dumai; 17. Menyediakan dan memasang alat OLT (Optical Line Terminal) dan CCR; 18. Bersedia memfasilitasi jaringan temporary yang diperlukan Pemerintah Kota Dumai di Wilayah Kota Dumai. 19. Menghubungkan Metro Link ke CCTV Kota Dumai sebanyak 12 Titik.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 720093);
