INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63175441', 63175441, 'analyze_legacy', 'Kementerian Kelautan Dan Perikanan', 'central', 'STASIUN KARANTINA IKAN PENGENDALIAN MUTU DAN KEAMANAN HASIL PERIKANAN BANDUNG', 'Belanja Jasa Lainnya', 'Jasa Lainnya', 'Dikecualikan', 'Jawa Barat, Cimahi (Kota)', 27500000, 'May 2026', 'APBN - PNBP (D)', 0, 1, '1 Paket', '1. Iuran Tahunan KAN (1 TAHUN) ( 1, PKT, @ 1500000 ); 2. Pendaftaran ( 1, PKT, @ 5000000 ); 3. Surveilen ISO 17020 ( 1, PKT, @ 21000000 );', '1. Iuran Tahunan KAN (Annual Fee) • Volume: Untuk masa berlaku 1 tahun. • Pagu Anggaran: Rp1.500.000,-. • Lingkup Pekerjaan: Pembayaran kewajiban tahunan sebagai Lembaga Penilaian Kesesuaian (LPK) terakreditasi. Pemeliharaan status akreditasi dalam database KAN dan publikasi pada direktori LPK nasional/internasional. • Output: Tanda terima pembayaran sah (Billing MPN/Simponi) dan status akreditasi tetap aktif di laman resmi KAN. 2. Biaya Pendaftaran (Application Fee) • Volume: Pendaftran registrasi. • Pagu Anggaran: Rp5.000.000,-. • Lingkup Pekerjaan: Pendaftaran permohonan siklus akreditasi baru, baik untuk re-akreditasi (perpanjangan masa berlaku sertifikat) maupun perluasan ruang lingkup inspeksi. Verifikasi administratif awal terhadap dokumen sistem mutu laboratorium oleh sekretariat KAN. • Output: Nomor registrasi permohonan dan jadwal rencana asesmen. 3. Surveilen ISO 17020 • Volume: on-site assessment. • Pagu Anggaran: Rp21.000.000,-. • Lingkup Pekerjaan: Pelaksanaan asesmen lapangan (on-site assessment) atau jarak jauh (remote assessment) oleh tim asesor KAN. Evaluasi konsistensi penerapan standar SNI ISO/IEC 17020:2012 pada Lembaga Inspeksi. Penilaian kompetensi teknis personel, ketertelusuran kalibrasi, serta validitas metode inspeksi di lapangan. Komponen biaya ini mencakup: Honorarium tim asesor (Ketua dan Anggota), biaya perjalanan dinas tim asesor (Tiket, Akomodasi, Uang Harian) sesuai SBM 2026. • Output: Laporan Hasil Asesmen (LHA) dan rekomendasi kelanjutan akreditasi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 722006);
