INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62659059', 62659059, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL ADMINISTRASI HUKUM UMUM', 'Pemeliharaan Infrastruktur Jaringan Direktorat Jenderal Administrasi Hukum Umum - DKI Jakarta Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 3500000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, PKT, @ 3500000000 )', '1. Pemeliharaan Infrastruktur Jaringan Ditjen AHU ( 1, PKT, @ 3500000000 );', 'a. Ruang Lingkup Infrastruktur Jaringan 1. Pemeliharaan Jaringan LAN Campus a) Penyedia melakukan pemeliharaan sesuai dengan yang telah dijadwalkan. b) Preventive maintenance yaitu melakukan pemeliharaan dan pemantauan terhadap kondisi media transmisi jaringan LAN (kabel dan nirkabel) dan perangkat jaringan LAN (Hardware dan Software), melakukan backup konfigurasi, membuat laporan hasil pekerjaan preventive maintenance yaitu kondisi sebelum dan sesudah preventive maintenance, summary report, permasalahan dan rekomendasi yang dibukukan berupa hardcopy dan softcopy tiap bulannya. c) Corrective maintenance adalah penanggulangan masalah yang dilakukan apabila terjadi masalah/gangguan pada jaringan LAN terutama pada media transmisi (kabel dan nirkabel) dan perangkat yang terdapat dalam inventaris perangkat. Hasil dari corrective maintenance dibukukan berupa hardcopy dan softcopy yang meliputi kondisi sebelum dan sesudah pekerjaan corrective maintenance, summary report, permasalahan dan rekomendasi. 2. Pemeliharaan Jaringan DMZ a) Penyedia melakukan pemeliharaan sesuai dengan yang telah dijadwalkan. b) Preventive maintenance yaitu melakukan pemeliharaan dan pemantauan terhadap kondisi media transmisi jaringan DMZ dan perangkat jaringan DMZ (Hardware dan Software), melakukan backup konfigurasi, membuat laporan hasil pekerjaan preventive maintenance yaitu kondisi sebelum dan sesudah preventive maintenance, summary report, permasalahan dan rekomendasi yang dibukukan berupa hardcopy dan softcopy tiap bulannya. c) Corrective maintenance adalah penanggulangan masalah yang dilakukan apabila terjadi masalah/gangguan pada media transmisi dan perangkat yang terdapat dalam inventaris perangkat. Hasil dari corrective maintenance dibukukan berupa hardcopy dan softcopy yang meliputi kondisi sebelum dan sesudah pekerjaan corrective maintenance, summary report, permasalahan dan rekomendasi. Penyedia melakukan pemeliharaan sesuai dengan yang telah dijadwalkan. 3. Pemeliharaan Jaringan WAN a) Penyedia melakukan pemeliharaan sesuai dengan yang telah dijadwalkan. b) Preventive maintenance yaitu melakukan pemeliharaan dan pemantauan terhadap kondisi media transmisi jaringan WAN dan kondisi perangkat jaringan WAN (hardware dan software), melakukan backup konfigurasi, membuat laporan hasil pekerjaan preventive maintenance yaitu kondisi sebelum dan sesudah preventive maintenance, summary report, permasalahan dan rekomendasi yang dibukukan berupa hardcopy dan softcopy tiap bulannya. c) Corrective maintenance adalah penanggulangan masalah yang dilakukan apabila terjadi masalah/gangguan pada media transmisi dan perangkat yang terdapat dalam inventaris perangkat. Hasil dari corrective maintenance dibukukan berupa hardcopy dan softcopy yang meliputi kondisi sebelum dan sesudah pekerjaan corrective maintenance, summary report, permasalahan dan rekomendasi. b. Ruang Lingkup Keamanan Jaringan Ruang lingkup keamanan jaringan pada kegiatan Pemeliharaan Infrastruktur Jaringan Ditjen AHU secara umum meliputi kegiatan antara lain : 1) Penyedia melakukan pemeliharaan sesuai dengan yang telah dijadwalkan. 2) Preventive maintenance yaitu melakukan pemeliharaan dan pemantauan terhadap kondisi perangkat-perangkat keamanan jaringan (hardware dan software), melakukan backup konfigurasi, membuat laporan hasil pekerjaan preventive maintenance yaitu kondisi sebelum dan sesudah preventive maintenance, summary report, permasalahan dan rekomendasi yang dibukukan berupa hardcopy dan softcopy tiap bulannya. 3) Corrective maintenance adalah penanggulangan masalah yang dilakukan apabila terjadi masalah/gangguan pada fungsi perangkat keamanan jaringan. Hasil dari corrective maintenance dibukukan berupa hardcopy dan softcopy yang meliputi kondisi sebelum dan sesudah pekerjaan corrective maintenance, summary report, permasalahan dan rekomendasi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 722720);
