INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63173945', 63173945, 'analyze_legacy', 'Provinsi Sulawesi Tenggara', 'provinsi', 'DINAS KELAUTAN DAN PERIKANAN', 'Belanja Jasa Penyelenggaraan Acara (PERESMIAN KAMPUNG NELAYAN MERAH PUTIH)', 'Jasa Lainnya', 'E-Purchasing', 'Sulawesi Tenggara, Konawe (Kab.)', 1000000000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Beban Jasa Penyelenggaraan Acara', 'Penyelenggaraan Acara Event Daerah', 250000000, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 723376);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62658536', 62658536, 'analyze_legacy', 'Kab. Banjarnegara', 'kabkota', 'Dinas Kesehatan', 'Pengadaan Jasa Konsultansi Manajemen Konstruksi', 'Jasa Konsultansi', 'Seleksi', 'Jawa Tengah, Banjarnegara (Kab.)', 929606740, 'January 2026', 'APBD', 1, 1, '1 paket', 'a. Secara umum Konsultan Manajemen Konstruksi memiliki tugas: 1) Melaksanakan penjaminan mutu (quality assurance) pelaksanaan pekerjaan mulai dari tahapan pelaksanaan konstruksi, sampai dengan serah terima akhir pekerjaan; 2) Membantu pengguna jasa dalam melakukan persetujuan atau penolakan perubahan Kontrak; 3) Membantu pengguna jasa dalam menghitung nilai perolehan aset barang milik negara; dan 4) Membantu pengguna jasa ketika dilakukan audit hasil pekerjaan/proyek setelah serah terima akhir pekerjaan. b. Tahap Tender Pelaksana Konstruksi Rancang Bangun: 1) Membantu pengelola kegiatan dalam mempersiapkan dan menyusun program pelaksanaan pelelangan pekerjaan konstruksi fisik; 2) Membantu unit layanan pengadaan barang dan jasa atau kelompok kerja unit layanan pengadaan barang dan jasa atau pejabat pengadaan dalam penyebarluasan pengumuman pelelangan, baik melalui papan pengumuman, media cetak, maupun media elektronik; 3) Membantu unit layanan pengadaan barang dan jasa atau kelompok kerja unit layanan pengadaan barang dan jasa atau pejabat pengadaan melakukan prakualifikasi calon peserta pelelangan (apabila pelelangan dilakukan melalui prakualifikasi); 4) Membantu memberikan penjelasan pekerjaan pada waktu rapat penjelasan pekerjaan; 5) Membantu unit layanan pengadaan barang dan jasa atau kelompok kerja unit layanan pengadaan barang dan jasa atau pejabat pengadaan dalam menyusun harga perhitungan sendiri (HPS) atau owner’s estimate (OE) pekerjaan konstruksi fisik; 6) Membantu melakukan pembukaan dan evaluasi terhadap penawaran yang masuk; 7) Membantu menyiapkan draft surat perjanjian pekerjaan pelaksanaan konstruksi fisik; 8) Menyusun laporan kegiatan pelelangan. c. Tahap Pelaksanaan Konstruksi Terintegrasi Rancang Bangunan: 1) Mengevaluasi program kegiatan pelaksanaan fisik yang disusun oleh penyedia jasa pelaksanaan konstruksi, yang meliputi program-program pencapaian sasaran fisik, penyediaan dan penggunaan sumber daya berupa: tenaga kerja, peralatan dan perlengkapan, bahan bangunan, informasi, dana, program quality assurance atau quality control dan program kesehatan dan keselamatan kerja (K3); 2) Mengendalikan program pelaksanaan konstruksi fisik, yang meliputi program pengendalian sumber daya, pengendalian biaya, pengendalian waktu, pengendalian sasaran fisik (kualitas dan kuantitas) hasil konstruksi, pengendalian perubahan pekerjaan, pengendalian tertib administrasi, pengendalian kesehatan dan keselamatan kerja. 3) Melakukan evaluasi program terhadap penyimpangan teknis dan manajerial yang timbul, usulan koreksi program dan Tindakan turun tangan, serta melakukan koreksi teknis bila terjadi penyimpangan; 4) Melakukan koordinasi antara pihak-pihak yang terlibat dalam pelaksanaan konstruksi fisik; 5) Bersama dengan penyedia jasa konstruksi melakukan pemeriksaan lapangan bersama, dan melakukan penyesuaian antara gambar, RAB dengan kondisi lapangan dalam rangka MC 0%, memeriksa dan menerbitkan Berita Acara MC-0% lengkap dengan lampiran teknis; 6) Memeriksa Laporan K3 Penyedia Jasa Konstruksi secara berkala dan bertanggung jawab atas pelaksanaan program Kesehatan dan Keselamatan Kerja (K3) selama pelaksanaan pekerjaan konstruksi; 7) Bertanggung jawab terhadap hasil pelaksanaan pekerjaan konstruksi sesuai penugasannya; 8) Memeriksa dan mengevaluasi dokumen Rencana Mutu Kontrak Penyedia Jasa Konstruksi; 9) Mengumpulkan data dan informasi di lapangan untuk memecahkan persoalan yang terjadi selama pekerjaan konstruksi; 10) Melakukan rapat-rapat lapangan secara berkala serta koordinasi dengan pihak-pihak yang terlibat dalam konstruksi fisik selama pelaksanaan kegiatan; 11) Melakukan kegiatan pengawasan yang terdiri atas: a) Memeriksa dan mempelajari dokumen untuk pelaksanaan konstruksi yang akan dijadikan dasar dalam pengawasan pekerjaan di lapangan dan Standar Nasional atau standar lainnya yang terkait dengan pelaksanaan konstruksi; b) Mengawasi pemakaian bahan, peralatan dan metode pelaksanaan, serta mengawasi ketepatan waktu dan biaya pekerjaan konstruksi. c) Mengawasi pelaksanaan pekerjaan konstruksi dari segi kualitas, kuantitas dan laju pencapaian volume atau realisasi fisik; d) Mengumpulkan data dan informasi di lapangan untuk memecahkan persoalan yang terjadi selama pekerjaan konstruksi; e) Menyelenggarakan rapat-rapat lapangan secara berkala, membuat laporan mingguan dan bulanan pekerjaan manajemen konstruksi, dengan masukan hasil-hasil rapat lapangan, laporan harian, mingguan dan bulanan pekerjaan konstruksi fisik yang dibuat oleh penyedia jasa pelaksanaan konstruksi; f) Menyusun laporan dan berita acara dalam rangka kemajuan pekerjaan dan pembayaran angsuran pekerjaan pelaksanaan konstruksi; g) Bersama dengan Penyedia Jasa Konstruksi melakukan pengukuran awal dilapangan dan menerbitkan Berita Acara Pengukuran Awal atau BA Mutual Check 0%; h) Memeriksa laporan progress kemajuan pekerjaan yang diajukan oleh Penyedia Jasa Konstruksi termasuk menjamin persetujuan Konsultan; i) Melakukan pengukuran lapangan bersama terhadap item pekerjaan terpasang pada saat pelaksanaan opname lapangan dan sebagai dasar diterbitkannya BA Opname Lapangan dan BA Kemajuan Pekerjaan; j) Melakukan pemeriksaan akhir pekerjaan dan menjamin semua item pekerjaan terpasang telah sesuai dengan BOQ Kontrak dan menerbitkan Berita Acara Pemeriksaan Akhir Pekerjaan; k) Meneliti gambar-gambar untuk pelaksanaan lapangan (shop drawing) yang diajukan oleh penyedia jasa pelaksanaan konstruksi; l) Memberikan rekomendasi Addendum Rencana Kerja dan Syarat (RKS) dan Addendum Kontrak jika ada perubahan lingkup dan atau penambahan lingkup pekerjaan; m) Meneliti gambar-gambar yang sesuai dengan pelaksaaan di lapangan (as built drawing) sebelum serah terima I; n) Menyusun daftar cacat atau kerusakan sebelum serah terima I dan mengawasi perbaikannya pada masa pemeliharaan; o) Bersama-sama dengan penyedia jasa perencanaan konstruksi menyusun petunjuk pemeliharaan dan penggunaan bangunan Gedung; p) Menyusun berita acara persetujuan kemajuan pekerjaan, serah terima pertama, berita acara pemeliharaan pekerjaan dan serah terima kedua pekerjaan konstruksi, sebagai kelengkapan untuk pembayaran angsuran pekerjaan konstruksi; q) Menerbitkan surat pernyataan keandalan bangunan selama umur bangunan sesuai yang dipersyaratkan dalam Kontrak Penyedia Jasa; r) Melakukan pemeriksaan dan membuat daftar simak seluruh item pekerjaan dan menyatakan kelaikan fungsi bangunan gedung terbangun sesuai dengan Persetujuan Bangunan Gedung (PBG); s) Membantu pengelola kegiatan dalam menyusun Dokumen Pendaftaran; t) Membantu pengelola kegiatan dalam penyiapan kelengkapan dokumen Sertifikat Laik Fungsi (SLF) dari Pemerintah Kabupaten atau Kota setempat; 12) Penyiapan dokumen untuk proses perizinan termasuk membantu memenuhi proses dan prosedur perizinan yang terkait dengan pelaksanaan pekerjaan; 13) Menghentikan pelaksanaan pekerjaan yang tidak sesuai persyaratan dalam Kontrak Penyedia Jasa Konstruksi; 14) Menerbitkan surat teguran kepada Penyedia Jasa Konstruksi jika terjadi keterlambatan pelaksanaan pekerjaan sesuai ketentuan Kontrak penyedia jasa konstruksi dan melaksanakan rapat pembuktian (Show Cause Meeting); 15) Melakukan koordinasi antara pihak-pihak yang terlibat dalam pelaksanaan konstruksi fisik; 16) Melakukan evaluasi terhadap penyimpangan teknis yang timbul, usulan koreksi dan tindakan turun tangan, serta melakukan koreksi teknis bila terjadi penyimpangan; 17) Menyusun laporan akhir pekerjaan manajemen konstruksi. d. Tahap Pemeliharaan Konstruksi Pada tahapan pemeliharaan konstruksi, konsultan manajemen konstruksi melaksanakan pengawasan pemeliharaan konstruksi sampai dengan serah terima pekerjaan kedua (FHO). Lingkup tugas pada tahap pemeliharaan konstruksi meliputi: 1) Menyusun daftar cacat/kerusakan akibat masa pemeliharaan dan mengawasi perbaikannya pada masa pemeliharaan sampai serah terima akhir; 2) Menyusun berita acara pemeliharaan pekerjaan dan serah terima akhir pekerjaan konstruksi. Laporan masa pemeliharaan dibuat dan dilaporkan kepada PPK setiap bulan.', 'a. Secara umum Konsultan Manajemen Konstruksi memiliki tugas: 1) Melaksanakan penjaminan mutu (quality assurance) pelaksanaan pekerjaan mulai dari tahapan pelaksanaan konstruksi, sampai dengan serah terima akhir pekerjaan; 2) Membantu pengguna jasa dalam melakukan persetujuan atau penolakan perubahan Kontrak; 3) Membantu pengguna jasa dalam menghitung nilai perolehan aset barang milik negara; dan 4) Membantu pengguna jasa ketika dilakukan audit hasil pekerjaan/proyek setelah serah terima akhir pekerjaan. b. Tahap Tender Pelaksana Konstruksi Rancang Bangun: 1) Membantu pengelola kegiatan dalam mempersiapkan dan menyusun program pelaksanaan pelelangan pekerjaan konstruksi fisik; 2) Membantu unit layanan pengadaan barang dan jasa atau kelompok kerja unit layanan pengadaan barang dan jasa atau pejabat pengadaan dalam penyebarluasan pengumuman pelelangan, baik melalui papan pengumuman, media cetak, maupun media elektronik; 3) Membantu unit layanan pengadaan barang dan jasa atau kelompok kerja unit layanan pengadaan barang dan jasa atau pejabat pengadaan melakukan prakualifikasi calon peserta pelelangan (apabila pelelangan dilakukan melalui prakualifikasi); 4) Membantu memberikan penjelasan pekerjaan pada waktu rapat penjelasan pekerjaan; 5) Membantu unit layanan pengadaan barang dan jasa atau kelompok kerja unit layanan pengadaan barang dan jasa atau pejabat pengadaan dalam menyusun harga perhitungan sendiri (HPS) atau owner’s estimate (OE) pekerjaan konstruksi fisik; 6) Membantu melakukan pembukaan dan evaluasi terhadap penawaran yang masuk; 7) Membantu menyiapkan draft surat perjanjian pekerjaan pelaksanaan konstruksi fisik; 8) Menyusun laporan kegiatan pelelangan. c. Tahap Pelaksanaan Konstruksi Terintegrasi Rancang Bangunan: 1) Mengevaluasi program kegiatan pelaksanaan fisik yang disusun oleh penyedia jasa pelaksanaan konstruksi, yang meliputi program-program pencapaian sasaran fisik, penyediaan dan penggunaan sumber daya berupa: tenaga kerja, peralatan dan perlengkapan, bahan bangunan, informasi, dana, program quality assurance atau quality control dan program kesehatan dan keselamatan kerja (K3); 2) Mengendalikan program pelaksanaan konstruksi fisik, yang meliputi program pengendalian sumber daya, pengendalian biaya, pengendalian waktu, pengendalian sasaran fisik (kualitas dan kuantitas) hasil konstruksi, pengendalian perubahan pekerjaan, pengendalian tertib administrasi, pengendalian kesehatan dan keselamatan kerja. 3) Melakukan evaluasi program terhadap penyimpangan teknis dan manajerial yang timbul, usulan koreksi program dan Tindakan turun tangan, serta melakukan koreksi teknis bila terjadi penyimpangan; 4) Melakukan koordinasi antara pihak-pihak yang terlibat dalam pelaksanaan konstruksi fisik; 5) Bersama dengan penyedia jasa konstruksi melakukan pemeriksaan lapangan bersama, dan melakukan penyesuaian antara gambar, RAB dengan kondisi lapangan dalam rangka MC 0%, memeriksa dan menerbitkan Berita Acara MC-0% lengkap dengan lampiran teknis; 6) Memeriksa Laporan K3 Penyedia Jasa Konstruksi secara berkala dan bertanggung jawab atas pelaksanaan program Kesehatan dan Keselamatan Kerja (K3) selama pelaksanaan pekerjaan konstruksi; 7) Bertanggung jawab terhadap hasil pelaksanaan pekerjaan konstruksi sesuai penugasannya; 8) Memeriksa dan mengevaluasi dokumen Rencana Mutu Kontrak Penyedia Jasa Konstruksi; 9) Mengumpulkan data dan informasi di lapangan untuk memecahkan persoalan yang terjadi selama pekerjaan konstruksi; 10) Melakukan rapat-rapat lapangan secara berkala serta koordinasi dengan pihak-pihak yang terlibat dalam konstruksi fisik selama pelaksanaan kegiatan; 11) Melakukan kegiatan pengawasan yang terdiri atas: a) Memeriksa dan mempelajari dokumen untuk pelaksanaan konstruksi yang akan dijadikan dasar dalam pengawasan pekerjaan di lapangan dan Standar Nasional atau standar lainnya yang terkait dengan pelaksanaan konstruksi; b) Mengawasi pemakaian bahan, peralatan dan metode pelaksanaan, serta mengawasi ketepatan waktu dan biaya pekerjaan konstruksi. c) Mengawasi pelaksanaan pekerjaan konstruksi dari segi kualitas, kuantitas dan laju pencapaian volume atau realisasi fisik; d) Mengumpulkan data dan informasi di lapangan untuk memecahkan persoalan yang terjadi selama pekerjaan konstruksi; e) Menyelenggarakan rapat-rapat lapangan secara berkala, membuat laporan mingguan dan bulanan pekerjaan manajemen konstruksi, dengan masukan hasil-hasil rapat lapangan, laporan harian, mingguan dan bulanan pekerjaan konstruksi fisik yang dibuat oleh penyedia jasa pelaksanaan konstruksi; f) Menyusun laporan dan berita acara dalam rangka kemajuan pekerjaan dan pembayaran angsuran pekerjaan pelaksanaan konstruksi; g) Bersama dengan Penyedia Jasa Konstruksi melakukan pengukuran awal dilapangan dan menerbitkan Berita Acara Pengukuran Awal atau BA Mutual Check 0%; h) Memeriksa laporan progress kemajuan pekerjaan yang diajukan oleh Penyedia Jasa Konstruksi termasuk menjamin persetujuan Konsultan; i) Melakukan pengukuran lapangan bersama terhadap item pekerjaan terpasang pada saat pelaksanaan opname lapangan dan sebagai dasar diterbitkannya BA Opname Lapangan dan BA Kemajuan Pekerjaan; j) Melakukan pemeriksaan akhir pekerjaan dan menjamin semua item pekerjaan terpasang telah sesuai dengan BOQ Kontrak dan menerbitkan Berita Acara Pemeriksaan Akhir Pekerjaan; k) Meneliti gambar-gambar untuk pelaksanaan lapangan (shop drawing) yang diajukan oleh penyedia jasa pelaksanaan konstruksi; l) Memberikan rekomendasi Addendum Rencana Kerja dan Syarat (RKS) dan Addendum Kontrak jika ada perubahan lingkup dan atau penambahan lingkup pekerjaan; m) Meneliti gambar-gambar yang sesuai dengan pelaksaaan di lapangan (as built drawing) sebelum serah terima I; n) Menyusun daftar cacat atau kerusakan sebelum serah terima I dan mengawasi perbaikannya pada masa pemeliharaan; o) Bersama-sama dengan penyedia jasa perencanaan konstruksi menyusun petunjuk pemeliharaan dan penggunaan bangunan Gedung; p) Menyusun berita acara persetujuan kemajuan pekerjaan, serah terima pertama, berita acara pemeliharaan pekerjaan dan serah terima kedua pekerjaan konstruksi, sebagai kelengkapan untuk pembayaran angsuran pekerjaan konstruksi; q) Menerbitkan surat pernyataan keandalan bangunan selama umur bangunan sesuai yang dipersyaratkan dalam Kontrak Penyedia Jasa; r) Melakukan pemeriksaan dan membuat daftar simak seluruh item pekerjaan dan menyatakan kelaikan fungsi bangunan gedung terbangun sesuai dengan Persetujuan Bangunan Gedung (PBG); s) Membantu pengelola kegiatan dalam menyusun Dokumen Pendaftaran; t) Membantu pengelola kegiatan dalam penyiapan kelengkapan dokumen Sertifikat Laik Fungsi (SLF) dari Pemerintah Kabupaten atau Kota setempat; 12) Penyiapan dokumen untuk proses perizinan termasuk membantu memenuhi proses dan prosedur perizinan yang terkait dengan pelaksanaan pekerjaan; 13) Menghentikan pelaksanaan pekerjaan yang tidak sesuai persyaratan dalam Kontrak Penyedia Jasa Konstruksi; 14) Menerbitkan surat teguran kepada Penyedia Jasa Konstruksi jika terjadi keterlambatan pelaksanaan pekerjaan sesuai ketentuan Kontrak penyedia jasa konstruksi dan melaksanakan rapat pembuktian (Show Cause Meeting); 15) Melakukan koordinasi antara pihak-pihak yang terlibat dalam pelaksanaan konstruksi fisik; 16) Melakukan evaluasi terhadap penyimpangan teknis yang timbul, usulan koreksi dan tindakan turun tangan, serta melakukan koreksi teknis bila terjadi penyimpangan; 17) Menyusun laporan akhir pekerjaan manajemen konstruksi. d. Tahap Pemeliharaan Konstruksi Pada tahapan pemeliharaan konstruksi, konsultan manajemen konstruksi melaksanakan pengawasan pemeliharaan konstruksi sampai dengan serah terima pekerjaan kedua (FHO). Lingkup tugas pada tahap pemeliharaan konstruksi meliputi: 1) Menyusun daftar cacat/kerusakan akibat masa pemeliharaan dan mengawasi perbaikannya pada masa pemeliharaan sampai serah terima akhir; 2) Menyusun berita acara pemeliharaan pekerjaan dan serah terima akhir pekerjaan konstruksi. Laporan masa pemeliharaan dibuat dan dilaporkan kepada PPK setiap bulan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 723377);
