INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63176255', 63176255, 'analyze_legacy', 'Kementerian Kelautan Dan Perikanan', 'central', 'STASIUN KARANTINA IKAN PENGENDALIAN MUTU DAN KEAMANAN HASIL PERIKANAN BANDUNG', 'Belanja Keperluan Perkantoran', 'Barang', 'Pengadaan Langsung', 'Jawa Barat, Cimahi (Kota)', 91000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 Paket', '1. Langganan Hosting Jesika Mobile ( 1, THN, @ 7000000 ); 2. Langganan Internet ( 12, BLN, @ 7000000 );', '1. Langganan Hosting Aplikasi "Jesika Mobile" Volume: 1 Tahun (Januari – Desember 2026). Pagu Anggaran: Rp7.000.000,- / Tahun. Tujuan: Menjamin ketersediaan infrastruktur server agar aplikasi "Jesika Mobile" dapat diakses secara stabil oleh pengguna selama 24/7. Spesifikasi Teknis Minimal: Jenis: Cloud Hosting atau Virtual Private Server (VPS). Penyimpanan: Minimal 50 GB SSD/NVMe (disesuaikan dengan ukuran database aplikasi). RAM/CPU: Minimal 4 GB RAM dan 2 Core CPU untuk kelancaran pemrosesan data. Bandwidth: Unmetered atau minimal 1 TB per bulan. Keamanan: Sertifikat SSL (HTTPS) aktif, fitur Daily Backup, dan perlindungan DDoS. SLA (Service Level Agreement): Uptime minimal 99,9%. Kewajiban Penyedia: Memberikan akses panel kontrol (seperti cPanel/DirectAdmin) dan dukungan teknis (support) jika terjadi kendala pada server. 2. Langganan Internet Volume: 12 Bulan. Pagu Anggaran: Rp7.000.000,- / Bulan (Total Rp84.000.000,- / Tahun). Tujuan: Menyediakan koneksi internet pita lebar (broadband/dedicated) untuk mendukung seluruh operasional kantor dan layanan digital. Spesifikasi Teknis Minimal: Tipe Koneksi: Dedicated Connection 1:1 atau Fiber Optic Broadband kualitas bisnis. Bandwidth: (Contoh estimasi: Minimal 100 Mbps - 200 Mbps) simetris antara upload dan download. IP Address: Minimal mendapatkan 1 buah IP Public Static (untuk keperluan remote access/server lokal). Layanan Tambahan: Termasuk peminjaman perangkat ONT/Router dan layanan maintenance jaringan lokal kantor. Ketentuan Layanan: Waktu tanggap perbaikan (Response Time) maksimal 4 jam setelah laporan gangguan diterima. Ketersediaan jaringan (Availability) minimal 99%.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 724662);
