INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63178264', 63178264, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'KANTOR PUSAT SEKRETARIAT JENDERAL', 'Belanja Perjalanan Dinas Paket Meeting Dalam Kota', 'Jasa Lainnya', 'Dikecualikan', 'DKI Jakarta, Jakarta Utara (Kota)', 27567000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Uang Harian Perjalanan Dinas Dalam Kota Lebih dari 8 Jam (D.K.I. Jakarta) ( 3, OH, @ 210000 ); 2. Uang Representasi Dalam Kota Pejabat Eselon II ( 6, OH, @ 75000 ); 3. Uang harian Fullboard ( 24, OH, @ 130000 ); 4. Biaya Penginapan Perjalanan Dinas Pejabat Eselon IV/Golongan III (D.K.I. JAKARTA) ( 3, OH, @ 730000 ); 5. Satuan Biaya Transport Kegiatan Dalam Kabupaten/Kota Pergi Pulang (PP) ( 16, OK, @ 170000 ); 6. Biaya Paket Kegiatan Rapat/Pertemuan Full Board di Luar Kantor - Pejabat Eselon III ke bawah (D.K.I. Jakarta) ( 16, OP, @ 1153564 );', 'Rekonsiliasi Penagihan/ Outstanding Belanja Barang dan Modal - 1. Uang Harian Perjalanan Dinas Dalam Kota Lebih dari 8 Jam (D.K.I. Jakarta) ( 3, OH, @ 210000 ); 2. Uang Representasi Dalam Kota Pejabat Eselon II ( 6, OH, @ 75000 ); 3. Uang harian Fullboard ( 24, OH, @ 130000 ); 4. Biaya Penginapan Perjalanan Dinas Pejabat Eselon IV/Golongan III (D.K.I. JAKARTA) ( 3, OH, @ 730000 ); 5. Satuan Biaya Transport Kegiatan Dalam Kabupaten/Kota Pergi Pulang (PP) ( 16, OK, @ 170000 ); 6. Biaya Paket Kegiatan Rapat/Pertemuan Full Board di Luar Kantor - Pejabat Eselon III ke bawah (D.K.I. Jakarta) ( 16, OP, @ 1153564 );', 27567000, 'high', 'Paket meeting dalam kota memuat komponen fullboard di luar kantor, uang harian, transport, dan penginapan di wilayah DKI Jakarta untuk kegiatan internal. Kombinasi ini mengindikasikan biaya rapat/perjalanan yang berpotensi tidak efisien karena kegiatan dalam kota pada prinsipnya dapat dilaksanakan tanpa penginapan dan skema fullboard yang mahal.', NULL, NULL, 3, 1, 1, 1, 1, 729048);
